// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // Get the current ceoAddress
        address currentCeo = c.ceoAddress();
        // If caller is the current ceo, call DrugDealer
        if (caller == currentCeo) {
            vm.prank(caller);
            c.DrugDealer();
            // After call, ceoAddress should be caller
            assertTrue(c.ceoAddress() == caller);
        } else {
            // If caller is not ceo, call should revert
            vm.prank(caller);
            vm.expectRevert("Only CEO can set new address");
            c.DrugDealer();
        }
    }
}

